input_grid = [
    [1, 6, 2, 4, 1],
    [3, 9, 9, 9, 9],
    [9, 9, 3, 9, 9],
    [0, 2, 9, 5, 4],
    [7, 9, 9, 9, 9]
]

n = 5
output = [[0 for _ in range(2*n)] for _ in range(2*n)]

# TL: original
for i in range(n):
    for j in range(n):
        output[i][j] = input_grid[i][j]

# TR: 90 deg clockwise
for i in range(n):
    for j in range(n):
        output[i][n+j] = input_grid[n-1-j][i]

# BL: 90 deg counter-clockwise
for i in range(n):
    for j in range(n):
        output[n+i][j] = input_grid[j][n-1-i]

# BR: 180 deg
for i in range(n):
    for j in range(n):
        output[n+i][n+j] = input_grid[n-1-i][n-1-j]

print("Final 10x10 output:")
for row in output:
    print(row)
